  "confidence": "low",
  "revision_action": "flip",
  "supportive_card_ids": ["C38", "C39", "C42", "C44"],
  "contradictory_card_ids": ["C16", "C05", "C13", "C18", "C20", "C01", "C02", "C04", "C09", "C06", "C07", "C14", "C21"],
  "prediction_basis_card_ids": ["C38", "C39", "C42", "C44"],
  "claims": [
    {
      "claim": "The query is a bicyclic prostaglandin-like free fatty acid, fully ionized at pH 7.4 with a carboxylic acid, cyclic hemiacetal, ketone, and gem-difluoride. The L3 oral-exposure records for structurally related free-acid/prostacyclin analogs show only pg/mL-level systemic exposure after oral dosing: arbaprostil Cmax 91.2 pg/mL (C39), treprostinil AUC0-48 2167 pg·h/mL and Cmin 51.45 pg/mL (C38, C42), and iloprost Cmax 86 pg/mL (C44). This pattern is consistent with extensive first-pass metabolism and low oral bioavailability in this chemical class.",
      "card_ids": ["C38", "C39", "C42", "C44"]
    },
    {
      "claim": "Misoprostol records (C41, C47, C48) are less transferable because misoprostol is a methyl-ester prodrug, whereas the query is a free acid; they do not provide affirmative evidence that the query exceeds 20% oral bioavailability.",
      "card_ids": ["C41", "C47", "C48"]
    },
    {
      "claim": "The L1/L2 high-F analogies (palmitic acid 28%, oxybate ~25-30%, neotame ≥34.3%, lefamulin ~25%, eplerenone 69-98%) come from different chemical classes and are outweighed by the more relevant prostaglandin-analog exposure pattern.",
      "card_ids": ["C16", "C05", "C13", "C18", "C20", "C01", "C02", "C04", "C09", "C06", "C07", "C14", "C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C38", "C39", "C42", "C44"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "L3 records are oral exposure values without IV comparators or complete dose information, so F cannot be computed directly.",
    "Reference prostaglandin analogs differ in prodrug status, formulation, species, and dose; misoprostol is a methyl-ester prodrug and less transferable.",
    "The query's unique hemiacetal, ketone, and gem-difluoride may alter metabolism and absorption in ways not captured by the visible records.",
    "L1/L2 high-F analogies are from different chemical classes and do not provide query-specific endpoint data."
  ],
  "decision_summary": "Flipped to low because the more structurally relevant L3 oral-exposure records for prostaglandin analogs show only pg/mL-level systemic exposure after oral dosing, consistent with low oral bioavailability in this class; combined with the query's full ionization and high flexibility, this outweighs the less relevant L1/L2 high-F analogies. Confidence is low because the L3 records are exposure-only and lack IV comparators."
}

